import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), [ (k,len(v),len(v[0])) for k,v in G.items()])

from collections import Counter
def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    H,W=h,w
    boxes=[]
    for r1 in range(H):
        for c1 in range(W):
            c=g[r1][c1]
            for r2 in range(r1+2,H):
                if g[r2][c1]!=c or g[r2][min(c1+1,W-1)]!=c: 
                    if g[r2][c1]!=c: break
                # check right col later; simpler: for each r2 where col c1 matches
                for c2 in range(c1+2,W):
                    if g[r1][c2]!=c: break
                    if g[r2][c2]!=c: continue
                    # border uniform c?
                    ok=all(g[r1][x]==c and g[r2][x]==c for x in range(c1,c2+1))
                    ok=ok and all(g[y][c1]==c and g[y][c2]==c for y in range(r1,r2+1))
                    if not ok: continue
                    interior={(y,x) for y in range(r1+1,r2) for x in range(c1+1,c2)}
                    vals={g[y][x] for y,x in interior}
                    if len(vals)==1 and vals.pop()!=c:
                        boxes.append((r1,c1,r2,c2,c,interior))
    seen=set()
    for r1,c1,r2,c2,c,interior in boxes:
        if interior & seen: continue
        seen|=interior
        fill=2 if len(interior)%2==0 else 7
        for y,x in interior: out[y][x]=fill
    return out
for i in (1,2,3):
    p=transform(G[f'Demo pair {i} input'])
    print(i, p==G[f'Demo pair {i} output'])
